import{_ as e,o,c as i,ag as l}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"使用","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/use.md","filePath":"zh/guide/use.md","lastUpdated":1783295281000}'),t={name:"zh/guide/use.md"};function d(r,a,c,n,s,h){return o(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;使用&quot;">​</a></h1><p>EasyYapi 支持以下使用方法：</p><h2 id="方式一-快捷键导出" tabindex="-1">方式一：快捷键导出 <a class="header-anchor" href="#方式一-快捷键导出" aria-label="Permalink to &quot;方式一：快捷键导出&quot;">​</a></h2><ol><li>打开项目中包含 API 的文件，或者在 IDEA 左边项目文件区域选择文件或文件夹</li><li>使用快捷键 <code>Alt + Shift + E</code> (Windows/Linux) 或 <code>Ctrl + E</code> (macOS)</li><li>选择要导出的 API</li><li>选择导出渠道：<code>YApi</code> / <code>Markdown</code> / <code>Postman</code></li><li>点击 ✔ 按钮或按回车键完成导出</li></ol><h2 id="方式二-右键导出" tabindex="-1">方式二：右键导出 <a class="header-anchor" href="#方式二-右键导出" aria-label="Permalink to &quot;方式二：右键导出&quot;">​</a></h2><ol><li>打开项目中包含 API 的文件，或者在 IDEA 左边项目文件区域选择文件或文件夹</li><li>鼠标右键点击文件内容或文件夹</li><li>选择 <code>ExportYapi</code> / <code>ExportPostman</code> / <code>ExportMarkdown</code> 导出该文件或文件夹中所有的 API</li></ol><h2 id="方式三-调用-api" tabindex="-1">方式三：调用 API <a class="header-anchor" href="#方式三-调用-api" aria-label="Permalink to &quot;方式三：调用 API&quot;">​</a></h2><ol><li>打开项目中包含 API 的文件</li><li>右键文件内容选择 <code>Call</code></li><li>在 IDE 中直接发起 API 请求</li></ol><p>详见 <a href="./call">Call API</a>。</p><h2 id="仅导出选中的方法" tabindex="-1">仅导出选中的方法 <a class="header-anchor" href="#仅导出选中的方法" aria-label="Permalink to &quot;仅导出选中的方法&quot;">​</a></h2><p>自 v3.2.0 起，EasyYapi 在导出时会尊重方法级选择。在触发导出之前，在编辑器中选中一个或多个方法（通过光标定位或拖选覆盖方法的文本范围）——只会导出源方法匹配（或覆盖）所选方法的端点，而不是包含类中的所有端点。</p><p>这对所有导出渠道均生效（YApi、Postman、Markdown、cURL、HttpClient）。若未选中任何方法，则仍按以往行为导出整个包含类。</p>',12)])])}const P=e(t,[["render",d]]);export{u as __pageData,P as default};
